package com.petlis.service.impl;
import com.petlis.common.exception.BusinessException;import com.petlis.common.security.*;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.transaction.annotation.Transactional;
import java.util.*;import java.math.BigDecimal;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
@SpringBootTest @Transactional @EnabledIfEnvironmentVariable(named="PETLIS_LOCAL_DB_TEST",matches="true")
class LegacyMonthlyReportLocalDatabaseTest {
 @Autowired FeatureStore store;AccessService access;LegacyMonthlyReportService service;LegacyOrderDetailService details;int actor,test;long hospital,order;String prefix;
 @BeforeEach void setup(){assertTrue(System.getenv("DB_URL").startsWith("jdbc:mysql://127.0.0.1:13306/laboklin?"));prefix="it_month_"+UUID.randomUUID().toString().substring(0,8);actor=(int)store.insert("INSERT INTO lin_user(username,nickname,status) VALUES(?,'月报测试','normal')",prefix);access=mock(AccessService.class);when(access.current()).thenReturn(new CurrentActor(actor,Set.of(PlatformRole.ADMIN),Set.of(),Set.of(),new DataScope(true,Set.of(),Set.of(),null)));service=new LegacyMonthlyReportService(store,access,new LegacyReportLinks("https://petlis.invalid/","public-monthly-test-key"));details=new LegacyOrderDetailService(store,access,new LegacyReportLinks("https://petlis.invalid/","public-monthly-test-key"));hospital=store.insert("INSERT INTO lin_lb_infohospital(HospitalName,HospitalName_en,PayType,amount) VALUES(?,?,1,0)",prefix,prefix);order=LegacyDetailFixtures.order(store,prefix,actor);store.jdbc().update("UPDATE lin_lb_listdiagnosisproject SET InfoHospitalId=?,ReceiveSampleDt='2024-02-29 23:59:59',SampleStatus=2 WHERE ListDiagnosisProjectId=?",hospital,order);test=LegacyDetailFixtures.test(store,prefix);gate(true);store.jdbc().update("INSERT INTO lin_operational_config(config_key,config_value,description,updated_by) VALUES('legacy-order-details','{\"enabled\":true,\"writeEnabled\":true}','transaction-only monthly fixture',?) ON DUPLICATE KEY UPDATE config_value=VALUES(config_value),status='ACTIVE'",actor);}
 void gate(boolean read){store.jdbc().update("INSERT INTO lin_operational_config(config_key,config_value,description,updated_by) VALUES('legacy-monthly-reports',?,'transaction-only monthly test',?) ON DUPLICATE KEY UPDATE config_value=VALUES(config_value),status='ACTIVE'",store.encode(Map.of("enabled",read)),actor);}
 void detail(String price,int paid,int exempt){details.create(order,new LegacyOrderDetailService.CreateCommand(test,new BigDecimal(price),"10",new BigDecimal(price),prefix,0,"",0,exempt,paid,0,"mail","report","month_"+UUID.randomUUID().toString().replace("-","")));}
 @Test void originalViewGroupsByReceiveMonthAndKeepsPaidIgnoredAndExemptRules(){detail("12.50",0,0);detail("1.25",1,0);detail("2.75",2,0);detail("4.00",3,0);detail("5.00",4,0);detail("99.00",0,1);
  String mode=store.jdbc().queryForObject("SELECT @@SESSION.sql_mode",String.class);
  var result=service.list(hospital,"2024-02","2024-02",0,0,50);assertEquals(1,((Number)result.get("total")).intValue());@SuppressWarnings("unchecked") var rows=(List<Map<String,Object>>)result.get("items");var row=rows.get(0);assertEquals("2024-02",row.get("month"));assertEquals("12.50",row.get("unpaid"));assertEquals("8.00",row.get("paid"));assertEquals("5.00",row.get("ignored"));assertEquals(0,((Number)service.list(hospital,"2024-03","2024-03",null,0,50).get("total")).intValue());
  store.jdbc().update("INSERT INTO lin_lb_noticemail(HospId,PayMonth,IsSendMail,Remark,CreateDt,UpdateDt) VALUES(?,'2024-02',1,'fixture','2024-03-01','2024-03-02')",hospital);assertEquals(1,((Number)service.list(hospital,"2024-02","2024-02",1,0,50).get("total")).intValue());
  assertEquals(mode,store.jdbc().queryForObject("SELECT @@SESSION.sql_mode",String.class));
 }
 @Test void draftUsesInclusiveLeapMonthAndExplicitTemplatesWithoutMarkingNotification(){detail("12.50",0,0);detail("7.25",2,0);detail("99.00",0,1);long report=store.insert("INSERT INTO lin_lb_dictfinancereport(model_name,model_content) VALUES(?,?)",prefix,"{结算单位}|{结算月份}|{结束时间}|{总费用}|{总费用大写}|{表格内容}|{用户付款链接}");long mail=store.insert("INSERT INTO lin_lb_dictfinancemailreport(model_name,model_content,IsActive) VALUES(?,?,0)",prefix,"邮件 {总费用}");
  var before=store.one("SELECT * FROM lin_lb_listdiagnosisproject WHERE ListDiagnosisProjectId=?",order);var draft=service.draft(hospital,"2024-02",report,mail);assertEquals(3,((Number)draft.get("count")).intValue());assertEquals("12.50",draft.get("unpaid"));assertTrue(draft.get("reportHtml").toString().contains("2024-02-29"));assertTrue(draft.get("reportHtml").toString().contains("壹拾贰元伍角整"));assertEquals("邮件 12.50",draft.get("mailHtml"));assertEquals(false,draft.get("sendEnabled"));assertEquals(before,store.one("SELECT * FROM lin_lb_listdiagnosisproject WHERE ListDiagnosisProjectId=?",order));assertEquals(0,store.jdbc().queryForObject("SELECT COUNT(*) FROM lin_lb_noticemail WHERE HospId=?",Integer.class,hospital));
  store.jdbc().update("UPDATE lin_lb_listdiagnosisproject SET ReceiveSampleDt='2024-03-01 00:00:00' WHERE ListDiagnosisProjectId=?",order);assertEquals(0,((Number)service.draft(hospital,"2024-02",report,mail).get("count")).intValue());
 }
 @Test void missingLinksAndInvalidInputsAreExplicit(){long report=store.insert("INSERT INTO lin_lb_dictfinancereport(model_name,model_content) VALUES(?,?)",prefix,"{用户付款链接}");service=new LegacyMonthlyReportService(store,access,new LegacyReportLinks("",""));var draft=service.draft(hospital,"2024-02",report,null);assertEquals(true,draft.get("paymentLinkRequiredButMissing"));assertEquals("{用户付款链接}",draft.get("reportHtml"));
  var originalOrder=store.jdbc().queryForList("SELECT id FROM lin_lb_dictfinancereport");assertEquals(((Number)originalOrder.get(originalOrder.size()-1).get("id")).longValue(),((Number)service.draft(hospital,"2024-02",null,null).get("reportTemplateId")).longValue());
  assertEquals(400,assertThrows(BusinessException.class,()->service.list(hospital,"2024-03","2024-02",null,0,50)).getCode());assertEquals(400,assertThrows(BusinessException.class,()->service.draft(hospital,"2024-13",null,null)).getCode());gate(false);assertEquals(409,assertThrows(BusinessException.class,()->service.list(null,null,null,null,0,50)).getCode());doThrow(new BusinessException(403,"denied")).when(access).requireAdmin();assertEquals(403,assertThrows(BusinessException.class,service::capabilities).getCode());}
}
